import itertools, json
Aopts = ['KMP','LNP','KLN','MQR','LMQ']
Bopts = ['LPQ','NPR','LMP','MNR','KNP']
Adays = [{2,7},{1,6,7},{7},{8},{2,7}]
Bdays = [{4,6},{3},{2,8},{3},{6,7,8}]
people = set('KLMNPQR')
west = set('KPR')
As = [x for x in itertools.product(*Aopts) if len(set(x)) == 5]
Bs = [x for x in itertools.product(*Bopts) if len(set(x)) == 5]
feasible = []
for a in As:
    for b in Bs:
        common = set(a) & set(b)
        if len(common) != 3 or len(common & west) != 1:
            continue
        days = {p:set() for p in people}
        for p,d in zip(a, Adays): days[p].update(d)
        for p,d in zip(b, Bdays): days[p].update(d)
        score = sum(len(d) >= 3 for d in days.values())
        feasible.append((score, ''.join(a), ''.join(b)))
lo = min(feasible)
hi = max(feasible)
result = {'feasible_linkages':len(feasible), 'bounds':[lo[0],hi[0]], 'low_witness':{'A':lo[1], 'B':lo[2]}, 'high_witness':{'A':hi[1], 'B':hi[2]}, 'decision':'confirmed' if lo[0]>=4 else 'excluded' if hi[0]<4 else 'undetermined'}
print(json.dumps(result))
print('checks',len(As),len(Bs), {s:sum(x[0]==s for x in feasible) for s in sorted(set(x[0] for x in feasible))})
for row in (lo,hi):
    days={p:set() for p in people}
    for p,d in zip(row[1],Adays):days[p].update(d)
    for p,d in zip(row[2],Bdays):days[p].update(d)
    print(row, sorted((p, sorted(d)) for p,d in days.items()))

